import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    os_type = platform.system()
    records = []
    start_time = time.time()
    while time.time() - start_time < duration:
        if os_type == "Windows":
            output = subprocess.check_output(['wmic', 'cpu', 'get', 'loadpercentage'], shell=True).decode()
            for line in output.split('\n'):
                if line.strip().isdigit():
                    cpu_usage = float(line.strip())
                    break
        else:
            output = subprocess.check_output(['top', '-bn1'], shell=True).decode()
            for line in output.split('\n'):
                if 'Cpu(s)' in line:
                    cpu_usage = 100.0 - float(line.split()[7])
                    break
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())
        records.append({'timestamp': timestamp, 'cpu_usage': cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH

