import subprocess
import os
import threading
def task_func(script_path: str, timeout: int = 60) -> str:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"File not found: {script_path}")
    result = [None]
    def run_script():
        try:
            proc = subprocess.Popen(['python', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            result[0] = proc
            proc.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            proc.terminate()
            result[0] = 'timeout'
    thread = threading.Thread(target=run_script)
    thread.start()
    thread.join(timeout=timeout + 1)
    if thread.is_alive():
        if result[0] is not None and isinstance(result[0], subprocess.Popen):
            result[0].terminate()
        return "Terminating process due to timeout."
    if result[0] == 'timeout':
        return "Terminating process due to timeout."
    return "Script executed successfully."

