import csv
import os
def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError(f"Commands file not found: {commands_file_path}")
    commands = []
    with open(commands_file_path, 'r', newline='') as csvfile:
        reader = csv.reader(csvfile)
        for row in reader:
            if row:
                commands.append(row[0])
    os.makedirs(output_dir_path, exist_ok=True)
    output_files = []
    for idx, cmd in enumerate(commands, start=1):
        output_file = os.path.join(output_dir_path, f'command_{idx}_output.txt')
        try:
            result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
            if result.returncode == 0:
                with open(output_file, 'w') as f:
                    f.write(result.stdout)
            else:
                with open(output_file, 'w') as f:
                    f.write(f"Command failed with exit code {result.returncode}\nError output:\n{result.stderr}")
        except Exception as e:
            with open(output_file, 'w') as f:
                f.write(f"Exception occurred: {str(e)}")
        output_files.append(output_file)
    return output_files

