        raise TypeError("file_list must be a list")
    for f in file_list:
        if not isinstance(f, str):
            raise TypeError("Each file must be a string")
    exit_codes = []
    lock = threading.Lock()
    def run_file(file_path):
        try:
            result = subprocess.run(file_path, shell=True)
            with lock:
                exit_codes.append(result.returncode)
        except Exception:
            with lock:
                exit_codes.append(-1)
    threads = []
    for file_path in file_list:
